INSERT INTO `regulatory_alerts` VALUES
(1,'FDA','recall','Class I Recall: Baxter Healthcare Corrects Baxter ExactaMix Compounding Systems Due to Sensor Sensor Misalignment','baxter-exactamix-compounding-recall-class-i','Baxter is recalling ExactaMix 2400 and ExactaMix 1200 automated compounding devices due to intermittent weight calibration anomalies causing incorrect ingredient dispensing in parenteral nutrition.',NULL,'Class I','ExactaMix 2400 and ExactaMix 1200 Automated Compounders','Baxter Healthcare','Nationwide in the United States and international health jurisdictions.','2026-11-15 20:29:21','https://www.fda.gov/medical-devices/medical-device-recalls','Z-0921-2026','active','2026-11-18 01:59:21','2026-11-18 01:59:21'),
(2,'FDA','safety_communication','FDA Safety Communication: Cybersecurity Vulnerabilities Identified in Legacy DICOM Medical Imaging Gateways','fda-safety-comm-cybersecurity-dicom-gateways','The FDA CDRH warns healthcare providers regarding unauthenticated remote code execution vulnerabilities impacting specific third-party PACS and DICOM routing servers.',NULL,'Class II','Legacy DICOM Router Firmware builds prior to v3.8.4','Multiple PACS Integration Vendors','Worldwide healthcare facilities running exposed radiological networks.','2026-11-13 20:29:21','https://www.fda.gov/medical-devices/safety-communications','FDA-SC-2026-081','active','2026-11-18 01:59:21','2026-11-18 01:59:21'),
(3,'EMA','guidance','EMA Quality and Safety Notice: Implementation of Nitrosamine Impurity Risk Assessments in Synthetic Drug Substances','ema-nitrosamine-impurity-risk-assessment-guidance','The European Medicines Agency issues comprehensive guidance reinforcing mandatory confirmatory testing and limit thresholds for N-nitrosamines in pharmaceutical APIs.',NULL,'Class II','Synthetic active pharmaceutical ingredients (APIs)','Global Pharmaceutical API Manufacturers','European Union Member States','2026-11-11 20:29:21','https://www.ema.europa.eu','EMA-QMS-2026-004','active','2026-11-18 01:59:21','2026-11-18 01:59:21'),
(4,'CDSCO','guidance','CDSCO Circular: Mandatory Registration & Audit Requirements for Class C & Class D Medical Devices in India','cdsco-circular-registration-audit-class-c-d-devices','Central Drugs Standard Control Organisation mandates online compliance portals and notified body inspection checklists for high-risk medical device imports.',NULL,'Class II','High-risk implantable and critical care medical devices','Domestic and international manufacturers marketing in India','India nationwide','2026-11-08 20:29:21','https://cdsco.gov.in','CDSCO-MD-2026-118','active','2026-11-18 01:59:21','2026-11-18 01:59:21'),
(5,'FDA','recall','FDA Class II: Victory Medical Center Pharmacy Recalls THYMOSIN ALPHA-1 (MDV) 3MG/ML **5ML**, VMC, Victory Medical Center Pharmacy, Aus','fda-recall-victory-medical-center-pharmacy-d-0145-2027-ac6186','Class II announced by FDA for THYMOSIN ALPHA-1 (MDV) 3MG/ML **5ML**, VMC, Victory Medical Center Pharmacy, Austin, Texas. Reason: Lack of Processing Controls...','\n      <p>The U.S. Food and Drug Administration (FDA) has posted an official drug enforcement report concerning <strong>Victory Medical Center Pharmacy</strong>.</p>\n      <h2>Product and Classification Details</h2>\n      <ul>\n        <li><strong>Recall Number:</strong> D-0145-2027</li>\n        <li><strong>Classification:</strong> Class II</li>\n        <li><strong>Recalling Firm:</strong> Victory Medical Center Pharmacy</li>\n        <li><strong>Status:</strong> Ongoing</li>\n      </ul>\n      <h2>Reason for Enforcement Action</h2>\n      <p>Lack of Processing Controls</p>\n      <h2>Distribution Information</h2>\n      <p>CO, FL, TX</p>\n      <blockquote>Official notification published per FDA Center for Drug Evaluation and Research (CDER) surveillance databases.</blockquote>\n    ','Class II','THYMOSIN ALPHA-1 (MDV) 3MG/ML **5ML**, VMC, Victory Medical Center Pharmacy, Austin, Texas','Victory Medical Center Pharmacy','CO, FL, TX','2026-11-10 18:30:00','https://www.fda.gov/drugs/drug-safety-and-availability/drug-recalls#D-0145-2027','D-0145-2027','active','2026-11-18 02:04:57','2026-11-18 02:04:57'),
(6,'FDA','recall','FDA Class II: Victory Medical Center Pharmacy Recalls CAGRILINTIDE/GLYCINE/B12 (MDV) 3.75/5/1MG/ML **1ML**, VMC, Victory Medical Cente','fda-recall-victory-medical-center-pharmacy-d-0122-2027-bb7c4a','Class II announced by FDA for CAGRILINTIDE/GLYCINE/B12 (MDV) 3.75/5/1MG/ML **1ML**, VMC, Victory Medical Center Pharmacy, Austin, Texas. Reason: Lack of Processing Controls...','\n      <p>The U.S. Food and Drug Administration (FDA) has posted an official drug enforcement report concerning <strong>Victory Medical Center Pharmacy</strong>.</p>\n      <h2>Product and Classification Details</h2>\n      <ul>\n        <li><strong>Recall Number:</strong> D-0122-2027</li>\n        <li><strong>Classification:</strong> Class II</li>\n        <li><strong>Recalling Firm:</strong> Victory Medical Center Pharmacy</li>\n        <li><strong>Status:</strong> Ongoing</li>\n      </ul>\n      <h2>Reason for Enforcement Action</h2>\n      <p>Lack of Processing Controls</p>\n      <h2>Distribution Information</h2>\n      <p>CO, FL, TX</p>\n      <blockquote>Official notification published per FDA Center for Drug Evaluation and Research (CDER) surveillance databases.</blockquote>\n    ','Class II','CAGRILINTIDE/GLYCINE/B12 (MDV) 3.75/5/1MG/ML **1ML**, VMC, Victory Medical Center Pharmacy, Austin, Texas','Victory Medical Center Pharmacy','CO, FL, TX','2026-11-10 18:30:00','https://www.fda.gov/drugs/drug-safety-and-availability/drug-recalls#D-0122-2027','D-0122-2027','active','2026-11-18 02:04:57','2026-11-18 02:04:57'),
